import{_ as t,a,o,a6 as r}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"Compare","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/shop/compare/index.md","filePath":"api/rest-api/shop/compare/index.md","lastUpdated":1787725411000}'),s={name:"api/rest-api/shop/compare/index.md"};function i(d,e,n,p,h,c){return o(),a("div",null,e[0]||(e[0]=[r('<h1 id="compare" tabindex="-1">Compare <a class="header-anchor" href="#compare" aria-label="Permalink to &quot;Compare&quot;">​</a></h1><p>The Compare menu lets a logged-in customer build a side-by-side comparison list of products. A customer can list their compare items, read a single one, add a product, remove one item, or clear the whole list.</p><h2 id="when-a-client-uses-this" tabindex="-1">When a client uses this <a class="header-anchor" href="#when-a-client-uses-this" aria-label="Permalink to &quot;When a client uses this&quot;">​</a></h2><p>The comparison list is per customer and, unlike the wishlist, is <strong>not scoped to a channel</strong> — the same rows come back everywhere. Guests cannot hold one.</p><p>Reads identify the compared product by <strong>path reference</strong> (<code>/api/shop/products/126</code>), not as a nested object, so a comparison table fetches those products separately to get their names, prices, and attribute values. The GraphQL compare query returns them nested in a single request.</p><p>There is no toggle here as there is for the wishlist: adding a product that is already on the list is rejected, and removal addresses the comparison row&#39;s own ID.</p><h2 id="building-a-comparison-table" tabindex="-1">Building a Comparison Table <a class="header-anchor" href="#building-a-comparison-table" aria-label="Permalink to &quot;Building a Comparison Table&quot;">​</a></h2><p>A comparison row carries <code>id</code>, timestamps, and path references to the product and customer — no product data at all. The table itself is built in two steps: list the rows here, take the numeric id from the end of each <code>product</code> path, then fetch those products for their names, prices, images, and attribute values.</p><p>Fetch the products in one call rather than one per row: the product listing accepts filters, so a single request can return the whole comparison set. The attribute values that make up the table&#39;s rows come from each product&#39;s detail payload.</p><p>The API sets no ceiling on how many products a customer may compare. A readable table usually tops out around four columns, so cap it client-side.</p><h2 id="adding-and-removing" tabindex="-1">Adding and Removing <a class="header-anchor" href="#adding-and-removing" aria-label="Permalink to &quot;Adding and Removing&quot;">​</a></h2><p>Adding a product that is already on the list is rejected with <code>400</code> and the message <code>This product is already in your comparison list</code> — expected on a double tap, and worth treating as &quot;already added&quot; rather than surfacing as an error. There is no toggle endpoint, so a control that both adds and removes has to track the row id and call Delete itself.</p><p>Delete addresses the <strong>comparison row</strong> id, not the product id. Clearing the whole list is a single call that answers <code>201</code> with a <code>deletedCount</code>, and it is safe to repeat on an already-empty list.</p><h2 id="flags-on-the-catalog" tabindex="-1">Flags on the Catalog <a class="header-anchor" href="#flags-on-the-catalog" aria-label="Permalink to &quot;Flags on the Catalog&quot;">​</a></h2><p>Product listing and detail responses carry an <code>isInCompare</code> flag per product, so a catalog grid can show which items are already being compared without reading this menu first. It is <code>0</code> for guests. Unlike its wishlist counterpart it is not channel-scoped, matching the comparison list itself.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Method &amp; Path</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/rest-api/shop/compare/list.html">Get Compare Items</a></td><td><code>GET /api/shop/compare_items</code></td><td>List the customer&#39;s compare items.</td></tr><tr><td><a href="/api/rest-api/shop/compare/get.html">Get Compare Item</a></td><td><code>GET /api/shop/compare_items/{id}</code></td><td>A single compare item.</td></tr><tr><td><a href="/api/rest-api/shop/compare/create.html">Create Compare Item</a></td><td><code>POST /api/shop/compare_items</code></td><td>Add a product to the compare list.</td></tr><tr><td><a href="/api/rest-api/shop/compare/delete.html">Delete Compare Item</a></td><td><code>DELETE /api/shop/compare_items/{id}</code></td><td>Remove one item.</td></tr><tr><td><a href="/api/rest-api/shop/compare/delete-all.html">Delete All Compare Items</a></td><td><code>POST /api/shop/delete-all-compare-items</code></td><td>Clear the whole compare list.</td></tr></tbody></table><p>The item routes use an underscore — <code>compare_items</code>, not <code>compare-items</code>. The clear-all route is the hyphenated one.</p><p>All Compare endpoints require the storefront key and a customer Bearer token — see <a href="/api/rest-api/authentication.html">Authentication</a>.</p>',19)]))}const u=t(s,[["render",i]]);export{m as __pageData,u as default};
